export interface TrailInfo {
  /** Stable database identifier. Use this as `:trail_id` for trail-scoped review APIs. */
  id: string
  /** Per-repo sequential identifier (GitHub PR style). */
  number: number
  branch: string | null
  base: string
  title: string
  body_document?: EditorDocumentSnapshot | null
  status: TrailStatus
  /** Phase of an `open` trail (`planning` before code changes, `building` after); `null` otherwise. */
  phase: TrailPhase | null
  type: TrailType
  author: TrailAuthor | null
  assignees: string[]
  created_at: string
  updated_at: string
  merged_at: string | null
  /** SHA of the merge-base commit captured when the trail was merged/closed. */
  merge_base_sha?: string | null
  /** SHA of the trail branch HEAD captured when the trail was merged/closed. */
  head_sha?: string | null
  priority: TrailPriority
  reviewers: TrailReviewer[]
  /** Logins explicitly assigned as reviewers (Entire-internal; may not have reviewed yet) */
  requested_reviewers?: string[]
  // Computed from thread
  comment_count: number
  unresolved_count: number
  // Computed from checkpoints (via branch match). Omitted from trail list responses.
  checkpoint_count?: number
  // True when the trail branch has commits that are not reachable from its base branch.
  has_code_changes?: boolean
  // Latest typed runner outputs for the Trail monitor section.
  monitors?: TrailMonitorResult[]
  // Legacy trail evaluation scores (kept for API compatibility; monitor results are canonical).
  confidence?: number
  risk?: number
  drift?: number
}

